'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const menu=$('.menu-toggle');
function closeMenu(){document.body.classList.remove('menu-open');menu?.setAttribute('aria-expanded','false')}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.body.classList.toggle('menu-open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.body.classList.contains('menu-open')){closeMenu();menu.focus()}$$('.dropdown[open]').forEach(d=>d.open=false)}if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const items=[menu,...$$('#main-nav a,#main-nav summary')].filter(x=>x.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$$('#main-nav a').forEach(a=>a.addEventListener('click',closeMenu));
const mq=matchMedia('(min-width:901px)');mq.addEventListener('change',e=>{if(e.matches)closeMenu()});
document.addEventListener('click',e=>{$$('.dropdown[open]').forEach(d=>{if(!d.contains(e.target))d.open=false})});
$$('.dropdown').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)$$('.dropdown').forEach(o=>{if(o!==d)o.open=false})}));
const sticky=$('.mobile-call'),hero=$('.hero');
let scrolling=false;function scrollState(){if(scrolling)return;scrolling=true;requestAnimationFrame(()=>{$('header')?.classList.toggle('scrolled',scrollY>30);sticky?.classList.toggle('show',scrollY>(hero?hero.offsetHeight:160));scrolling=false})}addEventListener('scroll',scrollState,{passive:true});scrollState();
function activate(button,selector){$$(selector).forEach(b=>{const on=b===button;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))})}
let serviceData;async function services(){return serviceData||(serviceData=await fetch('/services.json').then(r=>{if(!r.ok)throw Error('Services unavailable');return r.json()}))}
const tabs=$$('[data-service]');
async function selectTab(button){try{const list=await services(),s=list[Number(button.dataset.service)];tabs.forEach(b=>{const on=b===button;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});const panel=$('#service-panel');panel.setAttribute('aria-labelledby',button.id);panel.replaceChildren();const tag=document.createElement('span');tag.className='eyebrow';tag.textContent=s.short.toUpperCase()+' SYSTEMS';const title=document.createElement('h3');title.textContent=s.name;const p=document.createElement('p');p.textContent=s.intro;const link=document.createElement('a');link.className='text-link';link.href='/services/'+s.slug+'/';link.textContent='Explore service ';panel.append(tag,title,p,link);$('.system-visual')?.setAttribute('data-active',s.slug);const visual=$('.system-visual .service-illustration');if(visual){visual.src='/assets/services/'+s.slug+'.svg';visual.alt=s.short+' technical illustration'}}catch{location.href='/services/'}}
tabs.forEach((b,i)=>{b.addEventListener('click',()=>selectTab(b));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight'||e.key==='ArrowDown')n=(i+1)%tabs.length;if(e.key==='ArrowLeft'||e.key==='ArrowUp')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();tabs[n].focus();selectTab(tabs[n])}})});
$$('[data-property]').forEach(b=>b.addEventListener('click',()=>{activate(b,'[data-property]');const commercial=b.dataset.property==='commercial';$('#property-copy').innerHTML=commercial?'<span class="eyebrow">FOR YOUR BUSINESS</span><h3>Keep your property moving.</h3><p>Restrooms, shared fixtures, supply and drainage. Discuss operations, access and the maintenance needs of your property.</p><a class="text-link" href="/services/commercial-plumbing/">Explore commercial service </a>':'<span class="eyebrow">FOR YOUR HOME</span><h3>Comfort in every room.</h3><p>Kitchens, bathrooms, laundry connections and the supply behind them. Start with the fixtures and symptoms you know.</p><a class="text-link" href="/services/residential-plumbing/">Explore residential service </a>';const visual=$('.property-art .service-illustration');if(visual){visual.src='/assets/services/'+(commercial?'commercial-plumbing':'residential-plumbing')+'.svg';visual.alt=(commercial?'Commercial':'Residential')+' technical illustration'}}));
$$('[data-zone]').forEach(b=>b.addEventListener('click',async()=>{try{const list=await services();const topic=list[0].topics[Number(b.dataset.zone)];activate(b,'[data-zone]');$('.zone-output h3').textContent=topic[0];$('.zone-output p').textContent=topic[1]}catch{}}));
const plan={access:'Identify the responsible site contact, suite access and building entry requirements before the visit.',operations:'Describe the operational impact, occupied areas and any shutdown constraints. Confirm timing directly.',maintenance:'Prepare equipment details and recurring issue history. Discuss a plan based on actual conditions.'};
$$('[data-plan]').forEach(b=>b.addEventListener('click',()=>{activate(b,'[data-plan]');$('#plan-copy').textContent=plan[b.dataset.plan]}));
$('#pipe-range')?.addEventListener('input',e=>{$('#pipe-new').style.clipPath='inset(0 0 0 '+e.target.value+'%)'});
$('#flush-demo')?.addEventListener('click',e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));$('.heater-demo').classList.toggle('flushed',on);e.currentTarget.textContent=on?'Reset illustration':'Show flushing concept';$('#flush-status').textContent=on?'Concept: water movement may carry some sediment out. Actual results and suitability vary.':'Illustrative only. Suitability requires assessment.'});
const filters=['Sediment filtration targets suspended particles, subject to the system’s specified particle rating.','Activated carbon may address certain taste, odor or chemical concerns, depending on the product and documented performance.','Specialized treatment should be selected for an identified concern. Confirm documented capabilities and maintenance requirements.'];
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{activate(b,'[data-filter]');$('#filter-copy').textContent=filters[Number(b.dataset.filter)]}));
$('#jet-range')?.addEventListener('input',e=>{const v=e.target.value;$('.jet-nozzle').style.left=v+'%';$('.jet-water').style.width=v+'%';$('.buildup').style.clipPath='inset(0 0 0 '+v+'%)'});

const form=$('#contact-form');if(form){const city=new URLSearchParams(location.search).get('city');if(city)form.elements.city.value=city.slice(0,120);form.addEventListener('submit',async e=>{e.preventDefault();const status=$('#form-status');if(!form.reportValidity())return;const d=new FormData(form);if(d.get('website')){status.textContent='Unable to prepare this inquiry.';return}if(d.get('contact')==='Email'&&!d.get('email')){status.textContent='Enter your email for the preferred contact method.';form.elements.email.focus();return}const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Preparing summary…';status.textContent='';try{const lines=['SOLID CHOICE PLUMBING — INQUIRY NOTES','Not submitted. Call (562) 641-6364 to discuss service.','',...['name','phone','email','city','service','property','contact','description'].map(k=>k.toUpperCase()+': '+String(d.get(k)||''))];const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='solid-choice-inquiry.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);status.textContent='Your summary is ready for download. It has not been sent. Call (562) 641-6364 to arrange service.'}catch{status.textContent='The summary could not be downloaded. Call (562) 641-6364 instead.'}finally{button.disabled=false;button.textContent='Download inquiry summary '}})}
class BlueprintCinematicEntrance{
 constructor(el){this.el=el;this.video=el.querySelector('video');this.state='loading';this.token=0;this.config=null;this.reduced=matchMedia('(prefers-reduced-motion: reduce)');this.reduced.addEventListener('change',e=>{if(e.matches)this.finish('fallback')});this.bind();this.init()}
 setState(state){this.state=state;this.el.dataset.state=state;this.el.dispatchEvent(new CustomEvent('cinematicstatechange',{detail:state}))}
 seen(){try{return sessionStorage.getItem('sc-intro-v2')==='1'}catch{return false}}
 mark(){try{sessionStorage.setItem('sc-intro-v2','1')}catch{}}
 bind(){$('#skip-intro').addEventListener('click',()=>this.finish('skipped'));$('#replay-intro')?.addEventListener('click',()=>this.start());$('#sound-toggle').addEventListener('click',e=>{this.video.muted=!this.video.muted;e.currentTarget.setAttribute('aria-pressed',String(!this.video.muted));e.currentTarget.textContent=this.video.muted?'Sound off':'Sound on'});addEventListener('resize',()=>this.position());addEventListener('scroll',()=>{if(['ready','playing','transitioning'].includes(this.state)&&scrollY>80)this.finish('skipped')},{passive:true})}
 async init(){try{const r=await fetch('/media.json');if(!r.ok)throw Error();this.config=await r.json();if(!this.source()){this.finish('fallback');return}const replay=$('#replay-intro');if(replay)replay.hidden=this.reduced.matches;if(this.reduced.matches||this.seen()){this.setState('completed');return}this.start()}catch{this.finish('fallback')}}
 source(){if(!this.config)return null;return matchMedia('(max-width:650px)').matches?this.config.mobile:this.config.desktop}
 position(){if(this.el.hidden)return;const rect=$('.hero').getBoundingClientRect();this.el.style.top=Math.max(0,rect.top)+'px';this.el.style.left=rect.left+'px';this.el.style.width=rect.width+'px';this.el.style.height=Math.max(0,Math.min(rect.height,innerHeight-Math.max(0,rect.top)))+'px'}
 async start(){const src=this.source(),mobile=matchMedia('(max-width:650px)').matches,poster=mobile?this.config?.mobilePoster:this.config?.poster;if(!src||!poster||this.reduced.matches){this.finish('fallback');return}const run=++this.token;clearTimeout(this.watchdog);clearTimeout(this.fadeTimer);this.el.classList.remove('transitioning');this.setState('loading');this.video.muted=true;$('#sound-toggle').textContent='Sound off';$('#sound-toggle').setAttribute('aria-pressed','false');this.video.poster=poster;this.video.src=src;this.video.oncanplay=async()=>{if(run!==this.token)return;clearTimeout(this.watchdog);this.setState('ready');try{await this.video.play();if(run!==this.token){this.video.pause();return}$('.hero-image').src=poster;this.el.hidden=false;this.position();this.setState('playing');this.watchdog=setTimeout(()=>this.finish('fallback'),18000)}catch{this.finish('fallback')}};this.video.onerror=()=>{if(run===this.token)this.finish('fallback')};this.video.onended=()=>{if(run===this.token)this.fade()};this.video.ontimeupdate=()=>{if(run===this.token&&this.state==='playing'&&this.video.duration&&this.video.currentTime>=this.video.duration-.65)this.fade()};this.watchdog=setTimeout(()=>this.finish('fallback'),7000);this.video.load()}
 fade(){if(!['playing','ready'].includes(this.state))return;this.setState('transitioning');this.el.classList.add('transitioning');this.fadeTimer=setTimeout(()=>this.finish('completed'),650)}
 finish(state){this.token++;clearTimeout(this.watchdog);clearTimeout(this.fadeTimer);this.video.pause();this.el.hidden=true;this.video.oncanplay=null;if(state==='completed'||state==='skipped')this.mark();this.setState(state)}
}

if($('#cinematic'))window.blueprintEntrance=new BlueprintCinematicEntrance($('#cinematic'));
async function gallery(){if(!$('#project-gallery'))return;try{const r=await fetch('/projects.json');if(!r.ok)return;const projects=(await r.json()).filter(p=>p.verified&&p.images?.length);if(!projects.length)return;const container=$('#project-gallery'),dialog=$('#project-dialog');let index=0,photo=0,opener;
function show(){const p=projects[index],content=$('#project-details');content.replaceChildren();const img=document.createElement('img');img.src=p.images[photo].src;img.alt=p.images[photo].alt||p.title;const h=document.createElement('h2');h.textContent=p.title;const desc=document.createElement('p');desc.textContent=p.description;const link=document.createElement('a');link.href='/services/'+p.service+'/';link.className='text-link';link.textContent='Related service ';content.append(img,h,desc,link);if(p.images.length>1){const prev=document.createElement('button'),next=document.createElement('button');prev.textContent='Previous image';next.textContent='Next image';prev.className=next.className='button outline';prev.onclick=()=>{photo=(photo+p.images.length-1)%p.images.length;show()};next.onclick=()=>{photo=(photo+1)%p.images.length;show()};content.append(prev,next)}}
projects.forEach((p,i)=>{const b=document.createElement('button'),img=document.createElement('img'),h=document.createElement('h3');img.src=p.images[0].src;img.alt=p.images[0].alt||p.title;img.loading='lazy';h.textContent=p.title;b.append(img,h);b.addEventListener('click',()=>{index=i;photo=0;opener=b;show();dialog.showModal()});container.append(b)});$('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}catch{}}
gallery();

async function initCoverage(){
 const menuSearch=$('#nav-city-search');menuSearch?.addEventListener('input',()=>{const query=menuSearch.value.trim().toLocaleLowerCase();let count=0;$$('[data-city-name]').forEach(a=>{const found=a.dataset.cityName.toLocaleLowerCase().includes(query);a.hidden=!found;if(found)count++});$$('.area-menu-regions section').forEach(s=>s.hidden=![...s.querySelectorAll('[data-city-name]')].some(a=>!a.hidden));$('#nav-city-empty').hidden=count>0});
 if(!$('#city-search'))return;
 let regions;try{const response=await fetch('/regions.json');if(!response.ok)throw Error();regions=await response.json()}catch{return}
 const buttons=$$('[data-city]'),search=$('#city-search');let selectedRegion=regions[0];
 function selectRegion(region){selectedRegion=region;$$('[data-region]').forEach(b=>{const on=b.dataset.region===region.id;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});const map=$('#coverage-map');if(map)map.src='https://www.openstreetmap.org/export/embed.html?bbox=-118.7%2C33.25%2C-116.7%2C34.5&layer=mapnik&marker='+region.lat+'%2C'+region.lon;const link=$('.location-map-link');link.href='https://www.openstreetmap.org/search?query='+encodeURIComponent(region.name+', California');link.textContent='View '+region.name+' on map'}
 function selectCity(city,region){selectRegion(region);buttons.forEach(b=>b.classList.toggle('selected',b.dataset.city===city));const box=$('#city-result');box.replaceChildren();const tag=document.createElement('span');tag.className='eyebrow';tag.textContent=region.name.toUpperCase();const h=document.createElement('h2');h.textContent=city;const p=document.createElement('p');p.textContent='Residential, commercial and specialized plumbing inquiries in '+city+'. Call to confirm availability for your address and service needs.';const a=document.createElement('a');a.className='text-link';a.href='/contact/?city='+encodeURIComponent(city);a.textContent='Prepare your service details';box.append(tag,h,p,a);const link=$('.location-map-link');link.href='https://www.openstreetmap.org/search?query='+encodeURIComponent(city+', California');link.textContent='View '+city+' on map';history.replaceState(null,'','?city='+encodeURIComponent(city))}
 buttons.forEach(b=>b.addEventListener('click',()=>{const r=regions.find(r=>r.id===b.dataset.cityRegionId);selectCity(b.dataset.city,r);$('#city-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}));
 $$('[data-region]').forEach(b=>b.addEventListener('click',()=>{const r=regions.find(r=>r.id===b.dataset.region);selectRegion(r);$('#city-result').replaceChildren();const h=document.createElement('h2');h.textContent=r.name;const p=document.createElement('p');p.textContent='Explore the city directory below or call for service availability at your address.';$('#city-result').append(h,p);$('#'+r.id).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}));
 search.addEventListener('input',()=>{const query=search.value.trim().toLocaleLowerCase();let count=0;buttons.forEach(b=>{b.hidden=!b.dataset.city.toLocaleLowerCase().includes(query);if(!b.hidden)count++});$$('.city-region').forEach(s=>s.hidden=![...s.querySelectorAll('[data-city]')].some(b=>!b.hidden));$('#city-search-status').textContent=query?(count?count+' matching cities. Select one below.':'No matching city. Call (562) 641-6364 to ask about your community.') :''});
 search.addEventListener('change',()=>{const value=search.value.trim();const r=regions.find(r=>r.cities.some(c=>c.toLocaleLowerCase()===value.toLocaleLowerCase()));if(r)selectCity(r.cities.find(c=>c.toLocaleLowerCase()===value.toLocaleLowerCase()),r)});
 const city=new URLSearchParams(location.search).get('city');if(city){const r=regions.find(r=>r.cities.includes(city));if(r){search.value=city;selectCity(city,r)}}
}
initCoverage();
